const LOGO="./assets/images/gart-logo.png";
'use strict';
const TOPIC_IMAGES={"sport": "./assets/images/sport.jpg", "psychology": "./assets/images/psychology.jpg", "business": "./assets/images/business.jpg"};
// This file runs entirely in the browser. All state and people are fictional.
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const btn=(label,href,cls='')=>`<a class="btn ${cls}" href="#${href}">${label}</a>`;
const act=(label,action,cls='',extra='')=>`<button type="button" class="btn ${cls}" data-action="${action}" ${extra}>${label}</button>`;
const tag=(s,cls='')=>`<span class="tag ${cls}">${esc(s)}</span>`;
const notice=(title,text,cls='')=>`<div class="notice ${cls}" role="status"><h3>${esc(title)}</h3><p>${text}</p></div>`;
const field=(label,name,value='',type='text',extra='')=>`<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;
const area=(label,name,value='',extra='')=>`<label>${label}<textarea name="${name}" ${extra}>${esc(value)}</textarea></label>`;
const choice=(label,name,options,val='',extra='')=>`<label>${label}<select name="${name}" ${extra}>${options.map(o=>{let [v,l]=Array.isArray(o)?o:[o,o];return `<option value="${esc(v)}" ${v===val?'selected':''}>${esc(l)}</option>`}).join('')}</select></label>`;
const empty=(title,text,link='')=>`<div class="empty"><h3>${title}</h3><p>${text}</p>${link}</div>`;
const kv=rows=>`<dl class="kv">${rows.map(([k,v])=>`<div class="data-row"><dt>${esc(k)}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl>`;
const table=(headers,rows)=>`<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th scope="col">${h}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table></div>`;
const tr=cells=>`<tr>${cells.map(c=>`<td>${c}</td>`).join('')}</tr>`;
const now=()=>new Date().toLocaleString('ru-RU',{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'});
let state;
function resetState(){state={user:null,logged:false,staff:false,role:'owner',offline:false,mailConfirmed:false,filters:{period:'upcoming',format:'',city:'',direction:''},
 requests:[{id:'r1',name:'Алексей',surname:'Соколов',phone:'+7 900 000-00-01',email:'alexey@example.com',city:'Москва',social:'https://vk.com/example',dob:'1992-05-14',heardFrom:'Друзья',status:'pending',note:''}],
 events:[{id:'e1',name:'Тренировка в кругу своих',date:'18 ноября 2026',time:'10:00',iso:'2026-11-18',city:'Челябинск',place:'Тестовые данные',format:'Офлайн',direction:'Спорт',description:'Совместная тренировка с комфортной нагрузкой и знакомство с участниками.',conditions:'Свободная форма одежды. Уровень подготовки не важен.',status:'published'},
 {id:'e2',name:'Разговор о личных опорах',date:'21 ноября 2026',time:'19:00',iso:'2026-11-21',city:'Все города',place:'Тестовые данные',format:'Онлайн',direction:'Психология',description:'Встреча о поддержке, привычках и том, что помогает сохранять устойчивость.',conditions:'Участие для одобренных участников сообщества.',status:'published'},
 {id:'e3',name:'Знакомство предпринимателей',date:'24 ноября 2026',time:'18:30',iso:'2026-11-24',city:'Челябинск',place:'Тестовые данные',format:'Офлайн',direction:'Бизнес',description:'Обмен опытом, знакомство и обсуждение совместных инициатив.',conditions:'Участие для одобренных участников сообщества.',status:'published'},
 {id:'e4',name:'Прогулка и знакомство',date:'1 ноября 2026',time:'11:00',iso:'2026-11-01',city:'Челябинск',place:'Городской парк',format:'Офлайн',direction:'Спорт',description:'Прогулка участников сообщества.',conditions:'Встреча завершена.',status:'past'}],
 signups:[],messages:[{id:'m1',nick:'Дмитрий',time:'10:24',text:'Привет! Кто планирует прийти на тренировку 18 ноября?'},{id:'m2',nick:'Андрей',time:'10:28',text:'Я планирую. Буду рад познакомиться на встрече.'},{id:'m3',nick:'Дмитрий',time:'10:30',text:'Отлично, увидимся!'}],complaints:[],journal:[],
 content:[{id:'about',title:'О проекте',text:'ГАРТ — сообщество для общения, взаимной поддержки и совместных дел. Спорт, психология и бизнес объединяют участников с разным опытом.',status:'published'},
 {id:'founder',title:'Владимир — создатель ГАРТ',text:'Владимир задумал ГАРТ как круг, в котором мужчины могут открыто общаться, находить поддержку и переходить от разговоров к совместным делам. Идея сообщества — объединить спорт, психологию и бизнес, чтобы каждый мог развиваться и помогать другим. Его цель — создать среду доверия, где ценят участие, взаимное уважение и инициативу.',status:'published'},
 {id:'media',title:'ГАРТ: сообщество, где знакомство становится поддержкой',text:'Мужчины встречаются, чтобы вместе тренироваться, обсуждать важные для них вопросы и обмениваться опытом. ГАРТ объединяет людей через общение и совместные дела: от первой встречи до новых инициатив внутри сообщества.',status:'published'},
 {id:'contacts',title:'Контакты',text:'Тестовые данные',status:'draft'},
 {id:'partner',title:'Партнёр сообщества',text:'Поддерживает встречи сообщества.',url:'https://example.com',status:'published',logo:''},
 {id:'legal',title:'Правовые документы',text:'',status:'draft',fileName:'',fileUrl:''}],
 permissions:{owner:['requests','users','complaints','content','events','roles','journal'],admin:['requests','users','complaints','content','events','journal'],tech:[]}}}
resetState();
const HEARD_FROM=['Друзья','Интернет','Сообщество ВК','СМИ'];
const JOIN_CHECKS=[
 ['consent','Согласен на обработку персональных данных'],
 ['adultConfirmed','Подтверждаю своё совершеннолетие'],
 ['rulesAccepted','Согласен с <a href="#/legal" target="_blank" rel="noopener">правилами сообщества</a>']
];
const roles={owner:'Владелец',admin:'Администратор',tech:'Технический специалист'};
const sections={requests:'Заявки',users:'Участники',complaints:'Жалобы',content:'Содержимое сайта',events:'Мероприятия',roles:'Роли и доступ',journal:'Журнал действий'};
const path=()=>decodeURIComponent(location.hash.slice(1)||'/');
const member=()=>state.user?.approved&&state.logged&&!state.user.blocked;
const permitted=s=>state.permissions[state.role].includes(s);
const log=(action,object,reason='')=>state.journal.unshift({time:now(),author:roles[state.role],action,object,reason});
function go(p){if(path()===p)render();else location.hash=p}
function toast(s){$('#toast')?.remove();document.body.insertAdjacentHTML('beforeend',`<div id="toast" class="toast" role="status">${esc(s)}</div>`);setTimeout(()=>$('#toast')?.remove(),4500)}
let lastFocus;
function modal(title,body){lastFocus=document.activeElement;$('#modal')?.remove();document.body.insertAdjacentHTML('beforeend',`<div id="modal" class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><header><h2 id="dialog-title">${esc(title)}</h2><button class="modal-close" aria-label="Закрыть" data-action="close">×</button></header>${body}</section></div>`);$('#modal button, #modal input')?.focus()}
function closeModal(){$('#modal')?.remove();lastFocus?.focus()}
function confirmDialog(title,text,action,id='',label='Подтвердить'){modal(title,`<p>${text}</p><div class="actions">${act(label,action,'',`data-id="${esc(id)}"`)}${act('Отмена','close','secondary')}</div>`)}
const reviewer=()=>`<aside class="review" aria-label="Управление демонстрацией"><strong>ПРОТОТИП · ДЕМОДАННЫЕ</strong><span class="review-note">Данные вымышлены. Отправка писем и платежи не выполняются.</span><nav>${act('Сайт','demo-site')}${act('Участник','demo-member')}${act('CRM','demo-crm')}<select aria-label="Роль сотрудника" id="review-role">${Object.entries(roles).map(([v,l])=>`<option value="${v}" ${state.role===v?'selected':''}>${l}</option>`).join('')}</select>${act('Как проверить','help')}${act('Сброс','reset','reset-demo')}</nav></aside>`;
function demoControls(){return `<div class="demo-controls">${path()==='/join'?act('Заполнить пример','fill-join'):''}${state.user?.approved&&!state.user.password?act('Открыть пример SMS','sms','',`data-id="${esc(state.user.requestId)}"`):''}${path()==='/chat'?`${act(state.offline?'Восстановить сеть':'Пример ошибки сети','demo-offline')}${act(state.user?.muted?'Снять запрет отправки':'Пример запрета отправки','demo-muted')}`:''}</div>`}
function header(){let p=path();let nav=[['/about','О проекте'],['/events','Мероприятия'],['/contacts','Контакты']];return `<header class="site-header"><div class="header-inner"><a class="brand" href="#/" aria-label="ГАРТ — главная"><img src="${LOGO}" alt="ГАРТ" width="88" height="67"></a><div class="mobile-title">СИЛА ВНУТРИ<br>ОПОРА СРЕДИ СВОИХ</div><nav class="nav" aria-label="Основное меню">${nav.map(([h,l])=>`<a href="#${h}" ${p===h?'class="active" aria-current="page"':''}>${l}</a>`).join('')}<a href="#/search" aria-label="Поиск по сайту">Поиск</a></nav><div class="header-actions">${btn('Пожертвовать','/donate','donate-button')}${btn('Чат','/chat','secondary')}${btn('Личный кабинет',member()?'/profile':'/login','dark')}</div><button type="button" class="btn ghost menu-toggle" data-action="menu" aria-label="Открыть меню">☰</button></div></header>`}
const footer=()=>`<footer class="site-footer"><div class="footer-inner"><p>ГАРТ · Сила внутри. Опора среди своих.</p><nav class="footer-links" aria-label="Нижнее меню"><a href="#/about">О проекте и партнёры</a><a href="#/contacts">Контакты</a><a href="#/legal">Правовая информация</a><a href="#/search">Поиск</a></nav></div></footer>`;
const container=(s,cls='')=>`<main id="main" class="container content ${cls}">${s}</main>`;
function eventCard(e){
 const schedule=member()?`${esc(e.date)} · ${esc(e.time)}<br>`:'';
 return `<article class="card event">${tag(e.format)}<h3>${esc(e.name)}</h3><div class="meta">${schedule}${esc(e.city)}</div><p class="muted">${esc(e.description)}</p>${btn('Подробнее',`/event/${e.id}`,'secondary small')}</article>`
}
function home(){return `<main id="main"><section class="hero"><div class="hero-inner"><div><div class="eyebrow">Сообщество ГАРТ</div><h1>Сила внутри.<br>Опора среди своих.</h1><p>Общение, поддержка и совместные дела. Найдите свой круг в спорте, психологии и бизнесе.</p><div class="actions">${btn('Вступить в сообщество','/join')}${btn('Смотреть мероприятия','/events','secondary')}</div></div><img class="hero-art" src="${LOGO}" alt="Логотип сообщества ГАРТ"></div></section><div class="container"><section class="section"><div class="eyebrow">Три направления</div><h2>То, что объединяет</h2><div class="grid">${[['Спорт','Движение, совместные тренировки и поддержка.','sport','Мужчины на совместной пробежке в парке'],['Психология','Разговор, обмен опытом и личная устойчивость.','psychology','Мужчины внимательно слушают друг друга во время беседы'],['Бизнес','Знакомство, совместные идеи и развитие.','business','Участники обсуждают идеи за рабочим столом']].map(([h,t,key,alt],i)=>`<article class="card direction-card"><img class="direction-image" src="${TOPIC_IMAGES[key]}" alt="${alt}" width="1000" height="1000" loading="lazy" decoding="async"><div class="direction-body"><div class="info-num">0${i+1}</div><h3>${h}</h3><p class="muted">${t}</p></div></article>`).join('')}</div></section><section class="section"><h2>Встретимся в сообществе</h2><div class="grid">${state.events.filter(e=>e.status==='published').slice(0,3).map(eventCard).join('')}</div></section><section class="card"><h2>Знакомство начинается с разговора</h2><p>Оставьте заявку. Команда свяжется с вами и сообщит решение после личного разговора.</p>${btn('Оставить заявку','/join')}</section></div></main>`}
function about(){let a=state.content.find(c=>c.id==='about'),p=state.content.find(c=>c.id==='partner'),f=state.content.find(c=>c.id==='founder'),m=state.content.find(c=>c.id==='media');return container(`<div class="eyebrow">Сообщество</div><h1>О проекте ГАРТ</h1><section class="section about-intro" aria-labelledby="about-us-title"><h2 id="about-us-title">О нас</h2><p class="lead">${esc(a.text)}</p><div class="grid two"><article class="card"><h3>Здесь можно быть собой</h3><p>Общий чат, встречи и поддержка участников помогают находить близких по духу людей.</p></article><article class="card"><h3>Знакомство начинается с разговора</h3><p>Оставьте заявку. Команда свяжется с вами, чтобы познакомиться и сообщить решение о вступлении.</p></article></div></section>${f?.status==='published'?`<section class="section" aria-labelledby="founder-title"><div class="section-heading"><h2 id="founder-title">Создатель сообщества</h2>${tag('Тестовые данные','sample-tag')}</div><article class="card founder-card"><div class="founder-mark" aria-hidden="true">В</div><div><div class="eyebrow">Идея и люди</div><h3>${esc(f.title)}</h3><p>${esc(f.text)}</p><p class="small muted">Тестовые данные</p></div></article></section>`:''}${m?.status==='published'?`<section class="section" aria-labelledby="media-title"><div class="section-heading"><h2 id="media-title">СМИ</h2>${tag('Тестовые данные','sample-tag')}</div><article class="card media-card"><div class="eyebrow">Пример публикации · Тестовые данные</div><h3>${esc(m.title)}</h3><p>${esc(m.text)}</p><p class="small muted">Тестовые данные. Это пример материала, а не реальная публикация СМИ.</p></article></section>`:''}<section class="section" aria-labelledby="partners-title"><h2 id="partners-title">Партнёры проекта</h2>${p.status==='published'?`<article class="card doc-item"><div class="partner-logo">${p.logo?`<img src="${p.logo}" alt="Логотип партнёра">`:'Тестовые данные'}</div><div style="flex:1"><h3>${esc(p.title)}</h3><p>${esc(p.text)}</p><a href="${safeURL(p.url)}" target="_blank" rel="noopener">Официальный сайт партнёра ↗</a></div></article>`:empty('Партнёры пока не опубликованы','Тестовые данные')}</section>${btn('Вступить в сообщество','/join')}`)}
function safeURL(s){try{let u=new URL(s);return ['http:','https:'].includes(u.protocol)?esc(u.href):'#'}catch{return '#'}}
function donate(){return container(`<div class="eyebrow">Поддержка проекта</div><h1>Пожертвования</h1><p class="lead">Реквизиты для добровольного перевода.</p><div class="card requisites"><dl>${['Получатель','ИНН','КПП','Расчётный счёт','Банк получателя','БИК','Корреспондентский счёт'].map(s=>`<div class="data-row"><dt>${s}</dt><dd>Тестовые данные</dd></div>`).join('')}</dl></div><div class="space"></div><p class="muted small">Пожертвование добровольное и не влияет на вступление в сообщество.</p>`)}
function legal(){let d=state.content.find(c=>c.id==='legal');return container(`<h1>Правовая информация</h1><p class="lead">Опубликованные документы проекта.</p>${d.status==='published'&&d.fileUrl?`<article class="card doc-item"><div><h3>${esc(d.fileName)}</h3><p class="small muted">Документ организации</p></div><div class="actions"><a class="btn secondary" href="${d.fileUrl}" target="_blank" rel="noopener">Открыть</a><a class="btn" href="${d.fileUrl}" download="${esc(d.fileName)}">Скачать</a></div></article>`:empty('Документы пока не опубликованы','Тестовые данные')}`)}
function join(){
 const checks=JOIN_CHECKS.map(([name,label])=>`<div class="span-2"><label class="check"><input name="${name}" type="checkbox" required><span>${label} *</span></label></div>`).join('');
 return container(`<h1>Заявка на вступление</h1><p class="lead">Расскажите о себе. После получения заявки команда свяжется с вами для знакомства.</p><form class="card form-card" data-form="join" novalidate><div class="form-grid">${field('Имя *','name','', 'text','autocomplete="given-name" required')}${field('Фамилия *','surname','','text','autocomplete="family-name" required')}${field('Телефон *','phone','','tel','autocomplete="tel" required')}${field('Email *','email','','email','autocomplete="email" required')}${field('Город проживания *','city','','text','autocomplete="address-level2" required')}${field('Дата рождения *','dob','','date','required')}${field('Ссылка на соцсеть *','social','','url','class="social" required')}${choice('Откуда вы о нас узнали?','heardFrom',[['','Выберите вариант'],...HEARD_FROM])}${checks}<div class="span-2"><p class="small muted">* Обязательные поля. Отправка заявки не открывает доступ к личному кабинету, чату и записи на мероприятия.</p><div class="actions"><button class="btn" type="submit">Отправить заявку</button>${btn('На главную','/','secondary')}</div></div></div></form>`)
}
function pending(){let r=state.requests.find(r=>r.id===state.user?.requestId);return container(`<div class="form-card narrow"><div class="eyebrow">Заявка на вступление</div><h1>${r?.status==='rejected'?'Решение по заявке':'Заявка получена'}</h1>${r?.status==='approved'?notice('Заявка одобрена','Проверьте email и SMS. В SMS находится ссылка для создания пароля.','success'):r?.status==='rejected'?notice('Заявка не одобрена','Решение направлено на указанный email. Учётная запись не создана.'):notice('Ожидайте звонка','Команда свяжется с вами по указанному телефону. После разговора решение придёт по email. При одобрении дополнительно придёт SMS для создания пароля.')}<p>До одобрения личный кабинет, чат и запись на мероприятия недоступны.</p><div class="actions">${btn('Смотреть афишу','/events','secondary')}${btn('На главную','/','secondary')}</div></div>`)}
function login(){return container(`<div class="form-card narrow"><h1>Вход в сообщество</h1><p class="lead">Для участников с одобренной заявкой.</p><form class="card stack" data-form="login" novalidate>${field('Email','email','','email','required autocomplete="username"')}${field('Пароль','password','','password','required autocomplete="current-password"')}<div class="form-error"></div><button class="btn" type="submit">Войти</button><a href="#/reset">Не помню пароль</a></form><div class="space"></div><p>Ещё не вступили? <a href="#/join">Оставить заявку</a></p></div>`)}
function passwordPage(reset=false){if(!state.user?.approved)return container(empty('Ссылка недоступна','Создание учётной записи возможно после одобрения заявки.',btn('На главную','/','secondary')));return container(`<div class="form-card narrow"><h1>${reset?'Новый пароль':'Создайте пароль'}</h1><p class="lead">${esc(state.user.email)} · Заявка одобрена</p><form class="card stack" data-form="password" novalidate>${field('Пароль','password','','password','required autocomplete="new-password"')}${field('Повторите пароль','repeat','','password','required autocomplete="new-password"')}<div class="form-error"></div><button class="btn" type="submit">Сохранить пароль</button></form></div>`)}
function profile(){let u=state.user;return container(`<div class="status-line">${tag('Участник','success')}${act('Выйти','logout','ghost')}</div><h1>Личный кабинет</h1><p class="lead">Личные данные доступны вам и сотрудникам с соответствующими полномочиями. В общем чате отображается ник.</p><form class="card form-card" data-form="profile" novalidate><div class="form-grid">${field('Имя *','name',u.name,'text','required')}${field('Телефон *','phone',u.phone,'tel','required')}${field('Ссылка на соцсеть *','social',u.social,'url','required')}${field('Дата рождения *','dob',u.dob,'date','required')}${field('Ник в сообществе *','nick',u.nick,'text','required')}${field('Увлечения','hobbies',u.hobbies||'') }<div class="span-2">${area('О себе','about',u.about||'')}</div><div class="span-2"><button class="btn" type="submit">Сохранить изменения</button></div></div></form><div class="space"></div><div class="actions">${btn('Общий чат','/chat','secondary')}${btn('Мои мероприятия','/events/mine','secondary')}${act('Удалить аккаунт','delete-self','danger')}</div>`)}
function events(){
 let f=state.filters;
 const cities=[...new Set(state.events.filter(e=>e.status!=='draft'&&e.city&&e.city!=='Все города').map(e=>e.city))].sort((a,b)=>a.localeCompare(b,'ru'));
 let list=state.events.filter(e=>e.status!=='draft'&&(f.period==='past'?e.status==='past':f.period==='mine'?state.signups.some(s=>s.eventId===e.id&&s.active):e.status==='published')&&(!f.format||e.format===f.format)&&(!f.city||e.city===f.city)&&(!f.direction||e.direction===f.direction));
 return container(`<div class="eyebrow">Сообщество в действии</div><h1>Мероприятия</h1><p class="lead">Выбирайте встречу по интересам и знакомьтесь с участниками.</p><div class="tabs" role="group" aria-label="Период">${[['upcoming','Предстоящие'],['past','Прошедшие'],['mine','Мои мероприятия']].map(([v,l])=>`<button class="tab ${f.period===v?'active':''}" data-action="period" data-id="${v}">${l}</button>`).join('')}</div><div class="filters">${choice('Формат','format',[['','Все форматы'],'Онлайн','Офлайн'],f.format,'data-filter')}${choice('Город','city',[['','Все города'],...cities],f.city,'data-filter')}${choice('Направление','direction',[['','Все направления'],'Спорт','Психология','Бизнес'],f.direction,'data-filter')}</div>${f.period==='mine'&&!member()?empty('Войдите, чтобы увидеть свои записи','Запись на мероприятие доступна одобренным участникам.',btn('Войти','/login')):list.length?`<div class="grid">${list.map(eventCard).join('')}</div>`:empty('Мероприятия не найдены','Измените фильтры или посмотрите предстоящие встречи.',act('Сбросить фильтры','reset-filters','secondary'))}`)
}
function eventDetail(id){
 let e=state.events.find(e=>e.id===id);if(!e)return notFound();
 const isMember=member();
 const signed=isMember&&state.signups.some(s=>s.eventId===id&&s.active);
 const offline=e.format==='Офлайн';
 const schedule=isMember?`<div><span>Дата и время</span><strong>${esc(e.date)}<br>${esc(e.time)}</strong></div>`:'';
 const location=`<div${isMember?'':' style="grid-column:1/-1"'}><span>${offline?'Место проведения':'Город и формат'}</span><strong>${esc(e.city)}<br>${esc(e.format)}</strong></div>`;
 const address=isMember?`<div><span>${offline?'Адрес':'Место'}</span><strong>${esc(e.place)}</strong></div>`:'';
 return container(`<div class="event-detail"><a class="crumb" href="#/events">← Все мероприятия</a><div class="space"></div>${tag(e.status==='past'?'Прошедшее':e.status==='cancelled'?'Отменено':e.format,e.status==='cancelled'?'danger':'')}<div class="space"></div><h1>${esc(e.name)}</h1><p class="lead">${esc(e.description)}</p><div class="event-meta">${schedule}${location}${address}</div><h2>Условия участия</h2><p>${esc(e.conditions)}</p>${e.status!=='published'?notice(e.status==='past'?'Встреча завершена':'Встреча отменена','Запись закрыта.'):signed?`${notice('Вы записаны','Свою запись можно найти в афише через «Мои мероприятия».','success')}${act('Отменить запись','cancel-signup','secondary',`data-id="${id}"`)}`:isMember?act('Участвовать','signup','',`data-id="${id}"`):`${notice('Для участников сообщества','Подробная информация о мероприятии и запись доступны после входа в учётную запись с одобренной заявкой.')}<div class="actions">${btn('Войти','/login')}${btn('Оставить заявку','/join','secondary')}</div>`}</div>`)
}
function chat(){let u=state.user;return container(`<h1>Общий чат</h1><div class="chat-layout"><aside class="card chat-rail">${tag('Только участники','success')}<h3>Наш круг общения</h3><p class="muted small">Уважайте собеседников. Жалобу можно отправить из меню сообщения или профиля.</p>${btn('Мероприятия','/events','secondary full')}${btn('Мой профиль','/profile','secondary full')}</aside><section class="card chat-panel" aria-label="Общий чат"><div class="chat-title"><div><h3>ГАРТ · Общение</h3><span class="small muted">Сообщения участников</span></div>${tag(u.muted?'Отправка ограничена':'Доступ открыт',u.muted?'warning':'success')}</div><div class="messages" aria-live="polite">${state.messages.filter(m=>!m.hidden).map(m=>`<article class="message ${m.mine?'mine':''}"><header><button class="link-btn" data-action="member-profile" data-id="${m.id}"><strong>${esc(m.nick)}</strong></button><time>${esc(m.time)}</time></header><p>${esc(m.text)}</p>${!m.mine?`<div class="message-actions"><button class="link-btn" data-action="complain" data-id="${m.id}">Пожаловаться</button></div>`:''}</article>`).join('')||empty('Пока нет сообщений','Начните разговор.')}</div>${u.muted?`<div class="chat-restriction">Отправка сообщений временно ограничена${u.mutedUntil?' до '+esc(u.mutedUntil):''}. История чата доступна для чтения.</div>`:''}<form class="composer" data-form="message" novalidate><div class="compose-row"><label style="flex:1">Сообщение<textarea name="text" placeholder="Напишите сообщение" ${u.muted?'disabled':''} aria-label="Текст сообщения"></textarea></label><button class="btn" type="submit" ${u.muted?'disabled':''}>Отправить</button></div><div class="form-error"></div></form></section></div>`,'chat-container')}
function notFound(){return container(empty('Страница не найдена','Проверьте адрес или вернитесь на главную.',btn('На главную','/')))}
function staffLogin(){return `<main class="container content"><div class="admin-login"><h1>Вход для команды</h1><p class="lead">Доступ к админ-панели сообщества.</p><form class="card stack" data-form="staff-login" novalidate>${field('Логин','login','','text','required autocomplete="username"')}${field('Пароль','password','','password','required autocomplete="current-password"')}<p class="small muted">Демонстрация: можно ввести любые непустые значения. Роль для проверки выбирается в верхней панели прототипа.</p><button class="btn" type="submit">Войти</button>${btn('На сайт','/','secondary')}</form></div></main>`}
function admin(p){if(!state.staff)return staffLogin();let parts=p.split('/'),section=parts[2]||'requests',id=parts[3];if(section==='request')section='requests';if(section==='event')section='events';let allowed=permitted(section);return `<main id="main" class="admin"><aside class="sidebar"><a class="brand" href="#/"><img src="${LOGO}" alt="ГАРТ"></a><div class="eyebrow">Работа сообщества</div><nav aria-label="Разделы CRM">${Object.entries(sections).filter(([s])=>permitted(s)).map(([s,l])=>`<a href="#/crm/${s}" class="${s===section?'active':''}">${l}</a>`).join('')||'<span class="small muted">Полномочия не выданы</span>'}</nav><div class="side-bottom">${btn('На сайт','/','secondary full')}${act('Выйти','staff-logout','ghost full')}</div></aside><div class="admin-main"><header class="admin-header"><h1>${esc(sections[section]||'Админ-панель')}</h1>${tag(roles[state.role])}</header><div class="admin-body">${allowed?adminContent(section,id):empty('Нет доступа к разделу','Для этой роли полномочие не выдано. Обратитесь к владельцу проекта.')}</div></div></main>`}
function adminContent(section,id){if(section==='requests'){if(id)return requestDetail(id);return `<p class="lead">Ручное рассмотрение после разговора с заявителем.</p>${table(['Заявитель','Контакты','Город','Статус',''],state.requests.map(r=>tr([`${esc(r.name)} ${esc(r.surname)}`,`${esc(r.email)}<br>${esc(r.phone)}`,esc(r.city),requestStatus(r.status),btn('Открыть',`/crm/request/${r.id}`,'secondary small')])))}${!state.requests.length?empty('Заявок пока нет','Отправьте заявку на сайте, чтобы пройти сценарий рассмотрения.') :''}`}
 if(section==='complaints')return complaints();
 if(section==='content'){if(id)return contentEditor(id);return `<p class="lead">Фиксированные разделы сайта. Порядок основного меню не меняется.</p>${table(['Раздел','Статус',''],state.content.map(c=>tr([esc(c.title),tag(c.status==='published'?'Опубликовано':'Черновик',c.status==='published'?'success':''),btn('Редактировать',`/crm/content/${c.id}`,'secondary small')])) )}`}
 if(section==='events'){if(id)return eventEditor(id);return `<div class="actions section">${btn('Создать мероприятие','/crm/event/new')}</div>${table(['Название','Дата','Формат','Статус',''],state.events.map(e=>tr([esc(e.name),esc(e.date),esc(e.format),tag({published:'Опубликовано',draft:'Черновик',past:'Прошедшее',cancelled:'Отменено'}[e.status]),btn('Открыть',`/crm/event/${e.id}`,'secondary small')])) )}`}
 if(section==='users')return users();
 if(section==='roles')return `<p class="lead">Три внутренние роли. Техническая роль сама по себе не открывает данные участников и чат.</p><form class="card stack" data-form="roles">${['admin','tech'].map(role=>`<fieldset style="border:1px solid #ddd;border-radius:6px;padding:20px"><legend>${roles[role]}</legend><div class="grid two">${Object.entries(sections).filter(([s])=>s!=='roles').map(([s,l])=>`<label class="check"><input type="checkbox" name="${role}-${s}" ${state.permissions[role].includes(s)?'checked':''}><span>${l}</span></label>`).join('')}</div></fieldset>`).join('')}<p class="small muted">Владелец сохраняет управление доступом. Полномочия технического специалиста в демонстрации изначально не выданы.</p><button class="btn" type="submit">Сохранить полномочия</button></form>`;
 if(section==='journal')return `<p class="lead">Решения и изменения сотрудников. Автор, время, объект и основание.</p>${state.journal.length?table(['Когда','Кто','Действие','Объект','Основание'],state.journal.map(j=>tr([esc(j.time),esc(j.author),esc(j.action),esc(j.object),esc(j.reason)||'—']))):empty('Действий пока нет','Решения по заявкам и модерации появятся здесь.')}`;
 return empty('Раздел не найден','Выберите раздел в меню.')}
function requestStatus(s){return tag({pending:'Ожидает решения',approved:'Одобрена',rejected:'Отказ'}[s],{pending:'warning',approved:'success',rejected:'danger'}[s])}
function requestDetail(id){let r=state.requests.find(r=>r.id===id);if(!r)return empty('Заявка не найдена','Вернитесь к списку заявок.');return `<a class="crumb" href="#/crm/requests">← Все заявки</a><div class="space"></div><div class="status-line">${requestStatus(r.status)}</div><div class="split"><section class="card"><h2>${esc(r.name)} ${esc(r.surname)}</h2>${kv([['Телефон',r.phone],['Email',r.email],['Город',r.city],['Дата рождения',r.dob],['Соцсеть',r.social],['Откуда вы о нас узнали?',r.heardFrom||'Не указано']])}</section><section class="card"><h2>Ручное рассмотрение</h2><form class="stack" data-form="request-note" data-id="${id}">${area('Внутренняя заметка','note',r.note||'')}<label class="check"><input name="called" type="checkbox" ${r.called?'checked':''}><span>Разговор с заявителем состоялся</span></label><button class="btn secondary" type="submit">Сохранить заметку</button></form><div class="space"></div>${r.status==='pending'?`<div class="actions">${act('Одобрить','approve','',`data-id="${id}"`)}${act('Отказать','reject','danger',`data-id="${id}"`)}</div><p class="small muted" style="margin-top:15px">Решение принимается сотрудником после разговора.</p>`:notice('Решение сохранено',r.status==='approved'?'Email: отправлен (демо). SMS со ссылкой создания пароля: отправлено (демо).':'Email с решением: отправлен (демо). Учётная запись не создана.',r.status==='approved'?'success':'')} </section></div>`}
function complaints(){return `<p class="lead">Проверка сообщений и профилей по жалобам. Основание решения сохраняется в журнале.</p>${state.complaints.length?`<div class="stack">${state.complaints.map(c=>{let m=state.messages.find(m=>m.id===c.messageId);return `<article class="card"><div class="status-line">${tag(c.done?'Рассмотрена':'Новая',c.done?'success':'warning')}${tag(c.type==='profile'?'Жалоба на профиль':'Жалоба на сообщение')}</div><h3>${esc(m?.nick||'Участник')}</h3>${c.type==='profile'?'':`<blockquote>${esc(m?.text||'Сообщение недоступно')}</blockquote>`}<p><strong>Причина:</strong> ${esc(c.reason)}</p>${!c.done?`<div class="actions">${act('Оставить без изменений','moderate','secondary',`data-id="${c.id}" data-kind="keep"`)}${act('Скрыть сообщение','moderate','secondary',`data-id="${c.id}" data-kind="hide" ${c.type==='profile'?'disabled':''}`)}${act('Удалить сообщение','moderate','danger',`data-id="${c.id}" data-kind="delete" ${c.type==='profile'?'disabled':''}`)}${act('Запретить отправку','moderate','secondary',`data-id="${c.id}" data-kind="mute"`)}</div>`:`<p class="small muted">Решение: ${esc(c.resolution)}</p>`}</article>`}).join('')}</div>`:empty('Новых жалоб нет','Отправьте жалобу в общем чате, чтобы пройти сценарий проверки.')}`}
function contentEditor(id){let c=state.content.find(c=>c.id===id);if(!c)return empty('Материал не найден','Вернитесь к списку разделов.');return `<a class="crumb" href="#/crm/content">← Разделы сайта</a><div class="space"></div><form class="card stack" data-form="content" data-id="${id}"><h2>${esc(c.title)}</h2>${field('Название','title',c.title,'text','required')}${id==='legal'?`<label>Файл PDF или DOCX<input type="file" name="document" accept=".pdf,.docx"></label><p class="small muted">${c.fileName?esc(c.fileName):'Файл не загружен'}</p>`:`${area(id==='partner'?'Краткое описание поддержки':'Текст','text',c.text)}${id==='partner'?`${field('Официальный сайт','url',c.url||'','url','required')}<label>Логотип<input type="file" name="image" accept="image/png,image/jpeg,image/svg+xml"></label>`:`<label>Обложка<input type="file" name="image" accept="image/png,image/jpeg"></label>${field('Теги','tags',c.tags||'')}`}`}<div class="form-grid">${field('Опубликовать с (необязательно)','from',c.from||'','datetime-local')}${field('Завершить публикацию (необязательно)','until',c.until||'','datetime-local')}</div>${choice('Статус','status',[['draft','Черновик'],['published','Опубликовано']],c.status)}<div class="form-error"></div><div class="actions"><button class="btn" type="submit">Сохранить</button>${btn('Отмена','/crm/content','secondary')}</div></form>`}
function eventEditor(id){let e=id==='new'?{id:'new',status:'draft',format:'Офлайн',direction:'Спорт',city:'Челябинск'}:state.events.find(e=>e.id===id);if(!e)return empty('Мероприятие не найдено','Вернитесь в список.');let signups=state.signups.filter(s=>s.eventId===id&&s.active);return `<a class="crumb" href="#/crm/events">← Все мероприятия</a><div class="space"></div><form class="card stack" data-form="event" data-id="${id}"><h2>${id==='new'?'Новое мероприятие':esc(e.name)}</h2>${field('Название *','name',e.name||'','text','required')}${area('Описание *','description',e.description||'','required')}<div class="form-grid">${field('Дата *','iso',e.iso||'','date','required')}${field('Время *','time',e.time||'','time','required')}${field('Город *','city',e.city||'','text','required')}${choice('Формат','format',['Офлайн','Онлайн'],e.format)}${choice('Направление','direction',['Спорт','Психология','Бизнес'],e.direction)}${field('Место или адрес подключения *','place',e.place||'','text','required')}</div>${area('Условия участия','conditions',e.conditions||'')}${choice('Статус','status',[['draft','Черновик'],['published','Опубликовано'],['cancelled','Отменено'],['past','Прошедшее']],e.status)}<div class="actions"><button class="btn" type="submit">Сохранить</button>${btn('Отмена','/crm/events','secondary')}</div></form>${id!=='new'?`<div class="space"></div><h2>Записавшиеся</h2>${signups.length?table(['Ник участника','Когда записался'],signups.map(s=>tr([esc(s.nick),esc(s.time)]))):empty('Пока нет записей','После записи участники появятся здесь.')}`:''}`}
function users(){let u=state.user;return u?.approved?`<div class="split"><article class="card"><div class="status-line">${tag(u.blocked?'Аккаунт заблокирован':'Участник',u.blocked?'danger':'success')}${u.muted?tag('Отправка сообщений ограничена','warning'):''}</div><h2>${esc(u.name)} ${esc(u.surname||'')}</h2>${kv([['Ник',u.nick],['Телефон',u.phone],['Email',u.email],['Дата рождения',u.dob],['Соцсеть',u.social]])}<form class="stack" data-form="user-note">${area('Внутренняя заметка','note',u.note||'')}<button class="btn secondary" type="submit">Сохранить заметку</button></form></article><article class="card"><h2>Доступ и ограничения</h2><p>Запрет отправки сообщений и блокировка аккаунта — отдельные решения.</p><div class="stack">${act(u.muted?'Снять запрет отправки':'Ограничить отправку сообщений','user-mute','secondary')}${act(u.blocked?'Разблокировать аккаунт':'Заблокировать аккаунт','user-block',u.blocked?'secondary':'danger')}${act('Удалить аккаунт','user-delete','danger')}</div></article></div>`:empty('Участников пока нет','Учётная запись появится после одобрения заявки.')}
function render(){closeModal();let p=path();document.title=`ГАРТ — ${p.startsWith('/crm')?'Админ-панель':'Прототип MVP'}`;$('#app').innerHTML=reviewer()+(p.startsWith('/crm')?admin(p):header()+publicPage(p)+footer());$('.review').insertAdjacentHTML('beforeend',demoControls());if(p==='/chat'&&member()){$('.messages').scrollTop=$('.messages').scrollHeight}window.scrollTo(0,0)}
function validate(form){
 let ok=true;
 form.querySelectorAll('.field-error').forEach(e=>e.remove());
 form.querySelectorAll('.invalid').forEach(e=>e.classList.remove('invalid'));
 for(let f of form.querySelectorAll('input,textarea,select')){
  if(f.checkValidity())continue;
  ok=false;f.classList.add('invalid');
  let msg=f.validity.valueMissing?(f.type==='checkbox'?'Отметьте обязательный пункт.':'Заполните обязательное поле.'):f.type==='email'?'Укажите корректный email.':f.type==='url'?'Укажите полную ссылку с https://.':'Проверьте значение.';
  const target=f.type==='checkbox'?(f.closest('label.check')||f):f;
  target.insertAdjacentHTML('afterend',`<span class="field-error" role="alert">${msg}</span>`);
 }
 if(!ok)form.querySelector('.invalid')?.focus();
 return ok
}
const demoUser=()=>({name:'Алексей',surname:'Соколов',phone:'+7 900 000-00-01',email:'alexey@example.com',city:'Москва',social:'https://vk.com/example',dob:'1992-05-14',heardFrom:'Друзья',nick:'Алексей',approved:true,password:'demo',requestId:'r1'});
document.addEventListener('submit',async ev=>{let f=ev.target;if(!f.matches('[data-form]'))return;ev.preventDefault();if(!validate(f))return;let d=Object.fromEntries(new FormData(f)),type=f.dataset.form,id=f.dataset.id;
 if(type==='join'){let r={...d,id:'r'+(state.requests.length+1),status:'pending',note:''};for(const [name] of JOIN_CHECKS)r[name]=f.elements[name].checked;state.requests.push(r);state.user={...r,requestId:r.id,approved:false};state.logged=false;go('/pending')}
 if(type==='login'){if(state.user?.approved&&d.email===state.user.email&&d.password===state.user.password&&!state.user.blocked){state.logged=true;go('/chat')}else f.querySelector('.form-error').innerHTML='<p class="field-error" role="alert">Не удалось войти. Проверьте данные и доступ к учётной записи.</p>'}
 if(type==='password'){if(d.password!==d.repeat){f.querySelector('.form-error').innerHTML='<p class="field-error" role="alert">Пароли не совпадают.</p>';return}state.user.password=d.password;state.logged=false;go('/login');toast('Пароль сохранён. Войдите в учётную запись.')}
 if(type==='reset'){modal('Проверьте почту','<p>Если для этого email существует учётная запись, мы отправим ссылку для восстановления пароля.</p><p class="small muted">В прототипе письмо не отправляется.</p>'+act('Понятно','close'))}
 if(type==='profile'){Object.assign(state.user,d);toast('Изменения сохранены')}
 if(type==='message'){if(!member()||state.user.muted)return;if(!d.text.trim()){f.querySelector('.form-error').innerHTML='<p class="field-error" role="alert">Введите сообщение.</p>';return}if(state.offline){f.querySelector('.form-error').innerHTML='<p class="field-error" role="alert">Не удалось отправить сообщение. Проверьте подключение и повторите отправку.</p>';return}state.messages.push({id:'m'+Date.now(),nick:state.user.nick,time:new Date().toLocaleTimeString('ru-RU',{hour:'2-digit',minute:'2-digit'}),text:d.text.trim(),mine:true});render();$('.composer textarea')?.focus()}
 if(type==='complaint'){state.complaints.unshift({id:'c'+Date.now(),messageId:id,reason:d.reason,type:f.dataset.kind||'message',done:false});closeModal();toast('Жалоба отправлена команде. Другие участники не видят её автора.')}
 if(type==='staff-login'){state.staff=true;go('/crm/requests')}
 if(type==='request-note'&&permitted('requests')){let r=state.requests.find(r=>r.id===id);r.note=d.note;r.called=!!d.called;log('Заметка по заявке',r.name);toast('Заметка сохранена')}
 if(type==='decision'&&permitted('requests')){let r=state.requests.find(r=>r.id===id);r.status=f.dataset.kind;r.reason=d.reason;log(r.status==='approved'?'Заявка одобрена':'Заявке отказано',r.name,d.reason);if(r.status==='approved'){state.user={...r,requestId:r.id,approved:true,nick:r.name,password:undefined};state.logged=false}else if(state.user?.requestId===r.id){state.user.approved=false;state.logged=false}render();toast('Решение сохранено. Уведомления показаны в демонстрационном режиме.')}
 if(type==='moderation'&&permitted('complaints')){let c=state.complaints.find(c=>c.id===id),m=state.messages.find(m=>m.id===c.messageId),kind=f.dataset.kind;if(kind==='hide'||kind==='delete')m.hidden=true;if(kind==='mute'){if(m?.mine&&state.user){state.user.muted=true;state.user.mutedUntil=d.until}c.resolution=`Запрет отправки до ${d.until}. ${d.reason}`}else c.resolution={keep:'Оставлено без изменений',hide:'Сообщение скрыто',delete:'Сообщение удалено'}[kind]+'. '+d.reason;c.done=true;log('Решение по жалобе',m?.nick||'Участник',c.resolution);render();toast('Решение сохранено')}
 if(type==='content'&&permitted('content')){let c=state.content.find(c=>c.id===id);if(d.from&&d.until&&d.until<=d.from){f.querySelector('.form-error').innerHTML='<p class="field-error">Окончание должно быть позже начала публикации.</p>';return}for(let k of ['title','text','url','tags','from','until','status'])if(k in d)c[k]=d[k];let file=f.querySelector('[name=document]')?.files[0];if(file){c.fileName=file.name;c.fileUrl=URL.createObjectURL(file)}let image=f.querySelector('[name=image]')?.files[0];if(image){c.logo=await new Promise(resolve=>{let reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.readAsDataURL(image)})}if(id==='legal'&&c.status==='published'&&!c.fileUrl){c.status='draft';toast('Сначала загрузите файл документа');return}log('Материал сохранён',c.title);go('/crm/content');toast('Изменения сохранены')}
 if(type==='event'&&permitted('events')){let e=state.events.find(e=>e.id===id);if(!e){e={id:'e'+Date.now()};state.events.unshift(e)}Object.assign(e,d);e.date=new Date(d.iso+'T12:00:00').toLocaleDateString('ru-RU',{day:'numeric',month:'long',year:'numeric'});log('Мероприятие сохранено',e.name);go('/crm/events');toast('Мероприятие сохранено')}
 if(type==='roles'&&state.role==='owner'){for(let r of ['admin','tech'])state.permissions[r]=Object.keys(sections).filter(s=>s!=='roles'&&d[`${r}-${s}`]);log('Изменены полномочия','Внутренние роли');toast('Полномочия сохранены')}
 if(type==='user-note'&&permitted('users')){state.user.note=d.note;log('Внутренняя заметка',state.user.nick);toast('Заметка сохранена')}
 if(type==='restriction'&&permitted('users')){let kind=f.dataset.kind;if(kind==='mute'){state.user.muted=true;state.user.mutedUntil=d.until}else state.user.blocked=true;log(kind==='mute'?'Запрет отправки сообщений':'Блокировка аккаунта',state.user.nick,d.reason);render();toast('Ограничение сохранено')}
 if(type==='search'){let q=d.query.trim().toLowerCase(),items=[['/about','О проекте, о нас, создатель, Владимир, СМИ и партнёры'],['/contacts','Контакты'],['/legal','Правовая информация'],['/events','Мероприятия'],...state.events.filter(e=>e.status!=='draft').map(e=>['/event/'+e.id,e.name])];let found=q?items.filter(([,t])=>t.toLowerCase().includes(q)):[];$('#search-results').innerHTML=found.length?`<div class="stack">${found.map(([h,t])=>`<article class="card"><h3><a href="#${h}">${esc(t)}</a></h3><p class="small muted">Публичный раздел сайта</p></article>`).join('')}</div>`:empty('Ничего не найдено','Попробуйте другой запрос.')}
});
function reasonForm(title,type,id,kind,body='',until=false){modal(title,`<form data-form="${type}" data-id="${id}" data-kind="${kind}" novalidate>${body}${area('Основание решения *','reason','','required')}${until?field('Ограничить до *','until','','datetime-local','required'):''}<div class="actions"><button class="btn" type="submit">Сохранить решение</button>${act('Отмена','close','secondary')}</div></form>`)}
document.addEventListener('click',ev=>{let b=ev.target.closest('[data-action]');if(!b||b.disabled)return;let a=b.dataset.action,id=b.dataset.id;
 if(a==='close')closeModal();
 if(a==='demo-site'){go('/')}
 if(a==='demo-member'){if(!state.user?.approved)state.user=demoUser();state.logged=true;state.user.blocked=false;go('/chat')}
 if(a==='demo-crm'){state.staff=true;go('/crm/requests')}
 if(a==='reset'){resetState();go('/');toast('Демонстрация сброшена')}
 if(a==='help')modal('Как проверить прототип',`<p>Верхняя тёмная панель — управление демонстрацией. Она не входит в интерфейс продукта.</p><ol><li><a href="#/join" data-action="close">Заявка</a> → заполнить форму → ожидание звонка.</li><li>«CRM» → открыть заявку → сохранить отметку о разговоре → одобрить или отказать.</li><li>После одобрения открыть пример SMS в верхней панели → создать пароль → войти.</li><li>«Участник» — быстрый переход к одобренному демонстрационному аккаунту. Можно отправить сообщение, пожаловаться и записаться на событие.</li><li>«CRM» → жалобы, мероприятия, содержимое сайта, роли и журнал.</li><li>Выбор технической роли показывает отсутствие доступа к личным данным.</li></ol><p class="small muted">Изменения живут до перезагрузки файла. Все сведения и события — примеры. Фирменные шрифты заменены на доступные аналоги.</p>${act('Начать проверку','close')}`);
 if(a==='fill-join'){let f=$('[data-form=join]'),u=demoUser();for(let k of ['name','surname','phone','email','city','social','dob','heardFrom'])f.elements[k].value=u[k];for(const [name] of JOIN_CHECKS)f.elements[name].checked=true;toast('Форма заполнена демонстрационными данными')}
 if(a==='menu')modal('Меню',`<nav class="stack">${[['/','Главная'],['/about','О проекте и партнёры'],['/events','Мероприятия'],['/contacts','Контакты'],['/legal','Правовая информация'],['/search','Поиск'],...(member()?[['/chat','Общий чат'],['/profile','Личный кабинет']]:[['/join','Вступить'],['/login','Войти']])].map(([h,l])=>`<a href="#${h}">${l}</a>`).join('')}</nav>`);
 if(a==='logout'){state.logged=false;go('/')}
 if(a==='staff-logout'){state.staff=false;go('/crm/login')}
 if(a==='period'){state.filters.period=id;go('/events')}
 if(a==='reset-filters'){state.filters={period:'upcoming',format:'',city:'',direction:''};render()}
 if(a==='signup'&&member()){state.signups.push({eventId:id,active:true,nick:state.user.nick,time:now()});render();toast('Вы записаны на мероприятие')}
 if(a==='cancel-signup')confirmDialog('Отменить запись?','Вы больше не будете в списке записавшихся на эту встречу.','confirm-cancel',id,'Отменить запись');
 if(a==='confirm-cancel'&&member()){state.signups.filter(s=>s.eventId===id).forEach(s=>s.active=false);render();toast('Запись отменена')}
 if(a==='complain'&&member()){modal('Жалоба на сообщение',`<form data-form="complaint" data-id="${id}" data-kind="message" novalidate>${area('Причина жалобы *','reason','','required')}<p class="small muted">Жалобу рассмотрит команда. Другие участники не видят её автора.</p><div class="actions"><button class="btn" type="submit">Отправить жалобу</button>${act('Отмена','close','secondary')}</div></form>`)}
 if(a==='member-profile'&&member()){let m=state.messages.find(m=>m.id===id);modal('Профиль участника',`<h3>${esc(m.nick)}</h3><p class="muted">Ник в сообществе</p>${!m.mine?act('Пожаловаться на профиль','profile-complaint','secondary',`data-id="${id}"`):btn('Мой профиль','/profile','secondary')}`)}
 if(a==='profile-complaint'&&member())modal('Жалоба на профиль',`<form data-form="complaint" data-id="${id}" data-kind="profile" novalidate>${area('Причина жалобы *','reason','','required')}<p class="small muted">Жалобу рассмотрит команда. Автор скрыт от других участников.</p><button class="btn" type="submit">Отправить жалобу</button></form>`);
 if(a==='demo-offline'){state.offline=!state.offline;render();toast(state.offline?'Демонстрация: сеть недоступна':'Демонстрация: сеть восстановлена')}
 if(a==='demo-muted'){state.user.muted=!state.user.muted;state.user.mutedUntil='';render()}
 if(a==='approve'&&permitted('requests')){let r=state.requests.find(r=>r.id===id);if(!r.called){toast('Сначала сохраните результат разговора с заявителем');return}reasonForm('Одобрить заявку?','decision',id,'approved','<p>Будет создана учётная запись. Решение придёт по email, ссылка для создания пароля — по SMS.</p>')}
 if(a==='reject'&&permitted('requests'))reasonForm('Отказать по заявке?','decision',id,'rejected','<p>Решение придёт по email. Учётная запись не создаётся.</p>');
 if(a==='sms'&&state.user?.approved)modal('Пример SMS после одобрения',`<p>ГАРТ: ваша заявка одобрена. Создайте пароль для входа в сообщество.</p>${btn('Создать пароль','/create-password')}<div class="space"></div><p class="small muted">Показано только для проверки прототипа. Реальное SMS не отправлялось.</p>`);
 if(a==='moderate'&&permitted('complaints'))reasonForm('Решение по жалобе','moderation',id,b.dataset.kind,'',b.dataset.kind==='mute');
 if(a==='user-mute'&&permitted('users')){if(state.user.muted){state.user.muted=false;log('Снят запрет отправки',state.user.nick);render()}else reasonForm('Ограничить отправку сообщений','restriction','','mute','<p>Участник сможет читать чат, но не отправлять сообщения.</p>',true)}
 if(a==='user-block'&&permitted('users')){if(state.user.blocked){state.user.blocked=false;log('Аккаунт разблокирован',state.user.nick);render()}else reasonForm('Заблокировать аккаунт','restriction','','block','<p>Закрытые функции сообщества станут недоступны. Это отдельное решение от запрета отправки в чате.</p>')}
 if(a==='delete-self')confirmDialog('Удалить аккаунт?','Доступ к личному кабинету и закрытым функциям будет прекращён.','confirm-delete-self','','Удалить аккаунт');
 if(a==='confirm-delete-self'){state.user=null;state.logged=false;state.signups=[];go('/');toast('Аккаунт удалён в демонстрации')}
 if(a==='user-delete'&&permitted('users'))confirmDialog('Удалить аккаунт участника?','Участник потеряет доступ к личному кабинету и закрытым функциям.','confirm-user-delete','','Удалить аккаунт');
 if(a==='confirm-user-delete'&&permitted('users')){log('Аккаунт удалён',state.user.nick);state.user=null;state.logged=false;state.signups=[];render();toast('Аккаунт удалён в демонстрации')}
});
document.addEventListener('change',ev=>{if(ev.target.id==='review-role'){state.role=ev.target.value;state.staff=true;go('/crm/requests')}if(ev.target.matches('[data-filter]')){state.filters[ev.target.name]=ev.target.value;render()}});
document.addEventListener('keydown',ev=>{let m=$('#modal');if(!m)return;if(ev.key==='Escape')closeModal();if(ev.key==='Tab'){let focus=[...m.querySelectorAll('a,button,input,textarea,select')].filter(n=>!n.disabled);let first=focus[0],last=focus.at(-1);if(ev.shiftKey&&document.activeElement===first){ev.preventDefault();last?.focus()}else if(!ev.shiftKey&&document.activeElement===last){ev.preventDefault();first?.focus()}}});
document.addEventListener('click',ev=>{if(ev.target.id==='modal')closeModal()});
window.addEventListener('hashchange',render);render();
function denied(){return container(empty(state.user?.blocked?'Доступ к сообществу ограничен':'Раздел для участников',state.user?.blocked?'Обратитесь к команде проекта, чтобы узнать о решении.':'Доступ откроется после одобрения заявки и входа в учётную запись.',`${btn('Контакты','/contacts','secondary')}${btn('Войти','/login')}`))}
function publicPage(p){if(['/profile','/chat'].includes(p)&&!member())return denied();if(p==='/')return home();if(p==='/about')return about();if(p==='/donate')return donate();if(p==='/legal')return legal();if(p==='/join')return join();if(p==='/pending')return pending();if(p==='/login')return login();if(p==='/create-password')return passwordPage();if(p==='/new-password')return passwordPage(true);if(p==='/profile')return profile();if(p==='/chat')return chat();if(p.startsWith('/events')){if(p==='/events/mine')state.filters.period='mine';return events()}if(p.startsWith('/event/'))return eventDetail(p.split('/')[2]);if(p==='/contacts')return container(`<h1>Контакты</h1><p class="lead">Связаться с командой проекта.</p><div class="card requisites">${kv([['Телефон','Тестовые данные'],['Email','Тестовые данные'],['Официальные страницы','Тестовые данные']])}</div>`);if(p==='/reset')return container(`<div class="form-card narrow"><h1>Восстановление пароля</h1><p class="lead">Введите email, указанный при вступлении.</p><form class="card stack" data-form="reset" novalidate>${field('Email','email','','email','required')}<button class="btn" type="submit">Получить ссылку</button>${btn('Вернуться ко входу','/login','secondary')}</form></div>`);if(p==='/search')return container(`<h1>Поиск по сайту</h1><form class="searchbox" data-form="search"><input name="query" aria-label="Поисковый запрос" placeholder="О проекте, мероприятиях, контактах…"><button class="btn" type="submit">Найти</button></form><div id="search-results"><p class="muted">Поиск по публичным разделам. Личные данные и чат не участвуют в поиске.</p></div>`);return notFound()}
